import json
import datetime
O = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
T = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
MO = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
SUF = {'0': 'dır', '1': 'dir', '2': 'dir', '3': 'tür', '4': 'tür', '5': 'tir', '6': 'dır', '7': 'dir', '8': 'dir', '9': 'dur'}
def three(n):
    p = []
    h = n // 100
    if h:
        p.append(('' if h == 1 else O[h] + ' ') + 'yüz')
    if (n // 10) % 10:
        p.append(T[(n // 10) % 10])
    if n % 10:
        p.append(O[n % 10])
    return ' '.join(p)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for div, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q = n // div
        n = n % div
        if q:
            out.append('bin' if (div == 1000 and q == 1) else three(q) + ' ' + name)
    if n:
        out.append(three(n))
    return ' '.join(out)
def amt(v, cur):
    v = round(abs(float(v or 0)), 2)
    a = int(v)
    k = int(round((v - a) * 100))
    if k >= 100:
        a += 1
        k = 0
    if cur == 'TL':
        return words(a) + (' lira ' + words(k) + ' kuruş' if k else ' Türk Lirası')
    nm = {'USD': 'dolar', 'EUR': 'euro', 'GBP': 'İngiliz Sterlini'}[cur]
    cn = 'peni' if cur == 'GBP' else 'sent'
    return words(a) + ' ' + nm + (' ' + words(k) + ' ' + cn if k else '')
def dt(s):
    d, m, y = str(s).split('.')
    return str(int(d)) + ' ' + MO[int(m) - 1] + ' ' + y
def dd(s):
    d, m, y = str(s).split('.')
    return datetime.date(int(y), int(m), int(d))
def sp(s):
    return ' '.join(O[int(c)] if c != '0' else 'sıfır' for c in str(s) if c.isdigit())
try:
    vars['balance_state'] = 'error'
    b = result.get('data')
    data = b.get('data') if isinstance(b, dict) else None
    if isinstance(data, dict) and not data.get('statementDate') and 'debtTL' in data:
        vars['reading_text'] = 'Sonu ' + sp(data.get('cardNumberLast4') or vars.get('card_last4')) + ' ile biten kartınız için henüz kesilmiş bir ekstre bulunmadığından borcunuz bulunmamaktadır.'
        vars['balance_state'] = 'ok'
    elif isinstance(data, dict) and data.get('statementDate'):
        today =datetime.date.fromisoformat(str(vars.get('now'))[:10])
        l4 = data.get('cardNumberLast4') or vars.get('card_last4')
        nm = (data.get('productName') or '').strip()
        who = 'Sonu ' + sp(l4) + ' ile biten ' + (nm + ' ' if nm else '') + 'kartınıza ait'
        stdate = data.get('statementDate')
        sent = []
        clear = []
        for cur, key, name in (('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')):
            x = data.get(key)
            if not isinstance(x, dict) or not x:
                continue
            rd = float(x.get('remainingDebt') or 0)
            if rd <= 0:
                clear.append(name)
                continue
            sd = x.get('statementDebt')
            mn = float(x.get('minPayment') or 0)
            rm = float(x.get('remainingMinPayment') or 0)
            if cur == 'TL':
                if rm > 0 and rm >= mn:
                    s = name + ' borcunuz ' + amt(sd, cur) + ', ödenmesi gereken minimum tutar ' + amt(mn, cur) + '.'
                elif rm <= 0:
                    s = name + ' borcunuz ' + amt(sd, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                else:
                    s = name + ' borcunuz ' + amt(sd, cur) + ', ödenmesi gereken minimum tutar ' + amt(mn, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + ', kalan minimum ödeme tutarınız ' + amt(rm, cur) + '.'
            else:
                s = name + ' borcunuz ' + amt(sd, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + ', ödenmesi gereken minimum tutar ' + amt(mn, cur) + '.'
            sent.append(s)
        tl = data.get('debtTL') or {}
        total_tl = amt(max(float(tl.get('totalDebt') or 0), 0), 'TL')
        due = dd(data.get('lastPayDate'))
        cut = dd(stdate)
        if cut == today:
            txt = 'Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. Toplam borcunuz ' + total_tl + '.'
        elif not sent:
            txt = 'Sonu ' + sp(l4) + ' ile biten ' + (nm + ' ' if nm else '') + 'kartınızın ' + dt(stdate) + ' tarihli ekstresinden borcunuz bulunmamaktadır. Gelecek dönemler dahil toplam borcunuz ' + total_tl + '. Son ödeme tarihiniz ' + dt(data.get('lastPayDate')) + ' olacaktır.'
        else:
            sent[0] = who + ' ' + dt(stdate) + ' tarihinde kesilen ekstre ' + sent[0]
            if clear:
                sent.append((clear[0] if len(clear) == 1 else ', '.join(clear[:-1]) + ' ve ' + clear[-1]) + ' borcunuz bulunmamaktadır.')
            if due < today and str(data.get('automaticPaymentFlag')) == 'Y' and float(data.get('remainAutomaticPaymentAmount') or 0) > 0:
                sent.append('Otomatik ödeme talimatınızdan çekilecek kalan tutar ' + amt(data.get('remainAutomaticPaymentAmount'), 'TL') + '.')
            if due == today:
                sent.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            elif due < today:
                sent.append('Son ödeme tarihiniz geçti. Toplam borcunuz ' + total_tl + '.')
            else:
                y = dt(data.get('lastPayDate'))
                sent.append('Borçlarınız için son ödeme tarihiniz ' + y + "'" + SUF[y[-1]] + '.')
            txt = ' '.join(sent)
        vars['reading_text'] = txt
        vars['card_last4'] = str(l4)
        vars['card_name'] = nm
        vars['balance_state'] = 'ok'
except Exception:
    vars['balance_state'] = 'error'

